mapper.select:


SELECT A.FACULTY_CODE facultyCode
FROM SIS_FACULTIES a 
where a.faculty_no = #{facultyNo}


SELECT lower(B.WEB_NAME)
FROM SIS_DEPTS a, SIS_INSTRUCTORS B 
where a.FACULTY_NO = #{facultyNo}
and a.dept_no = #{deptNo}
and A.INSTRUCTOR_ID = B.INSTRUCTOR_ID


SELECT A.DEPT_CODE  deptCode
FROM SIS_DEPTS a 
where a.FACULTY_NO = #{facultyNo}
and a.dept_no = #{deptNo}


select distinct 1 
from sis_faculties 
where  INSTRUCTOR_ID = #{instructorId}


select distinct 1 
from sis_depts 
where  INSTRUCTOR_ID = #{instructorId}

select count(1)
from   hrs_sections
where  staff_id = #{staffId}

select count(1)
from   hrs_sections
where  parent_section = #{sectionNo}
